#!/usr/bin/env bash
# install-offline.sh - install @TITLE@ (@EDITION@, @DISTRIBUTION@) on a host or cluster with NO network.
# Generated by tools/ship.mjs airgap (PRODUCT-ASSEMBLY-1 PA-8c). Run it from the unpacked air-gap folder:
#
#   bash install-offline.sh verify               check every file against SHA256SUMS (every command does this first)
#   bash install-offline.sh host [<dir>]         copy the Linux bundle to <dir> (default /opt/inspecto) and print how to
#                                                start it, or install it as a systemd service
#   bash install-offline.sh load [<registry>]    load the image into the local Docker (or containerd: ctr); with a
#                                                registry, retag it there and push, then print the helm install line
#
# Nothing here reaches the network: the bundle carries its own Java runtime and DuckDB extensions, the image its own base.
set -euo pipefail
self="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
# A relative install folder means relative to where the command was run, not to this bundle.
case "${2:-}" in ''|/*) ;; *) set -- "$1" "$PWD/$2" ;; esac
cd "$(dirname "$self")"

IMAGE_REF='@IMAGE_REF@'
IMAGE_REPO='@IMAGE_REPO@'
IMAGE_TAR='@IMAGE_TAR@'
CHART_TGZ='@CHART_TGZ@'
COMPLETE='@COMPLETE@'
MISSING='@MISSING@'

say() { printf '%s\n' "$*"; }
verify() {
    command -v sha256sum >/dev/null || { say "install-offline: sha256sum is needed (coreutils)"; exit 1; }
    sha256sum --quiet -c SHA256SUMS || { say "install-offline: a file does not match SHA256SUMS - the copy is damaged; copy the bundle again"; exit 1; }
    if [ "$COMPLETE" != true ]; then
        say "install-offline: WARNING - this bundle was built without these DuckDB extensions for linux_amd64: $MISSING"
        say "  the features that need them (xlsx, DuckLake output, Postgres scans, S3) fail at first use on this host."
    fi
}

cmd="${1:-}"
case "$cmd" in
    verify)
        verify; say "install-offline: all files match SHA256SUMS" ;;
    host)
        verify
        dest="${2:-/opt/inspecto}"
        mkdir -p "$dest"
        cp -R bundle/inspecto-deploy "$dest/"
        # A bundle zipped on Windows carries no executable bits.
        chmod +x "$dest"/inspecto-deploy/bin/*.sh "$dest"/inspecto-deploy/runtime/bin/*
        [ ! -f "$dest/inspecto-deploy/runtime/lib/jspawnhelper" ] || chmod +x "$dest/inspecto-deploy/runtime/lib/jspawnhelper"
        say "install-offline: installed to $dest/inspecto-deploy"
        say "  start:      $dest/inspecto-deploy/bin/serve.sh          (set AUTH_OIDC_* first for Standard and Advanced)"
        say "  as service: sudo $dest/inspecto-deploy/bin/install-service.sh" ;;
    load)
        verify
        registry="${2:-}"
        if command -v docker >/dev/null; then
            docker load -i "image/$IMAGE_TAR"
            if [ -n "$registry" ]; then
                docker tag "$IMAGE_REF" "$registry/$IMAGE_REF"
                docker push "$registry/$IMAGE_REF"
            fi
        elif command -v ctr >/dev/null; then
            [ -z "$registry" ] || { say "install-offline: pushing to a registry needs docker; load with ctr, then push with your registry's tool"; exit 1; }
            ctr -n k8s.io images import "image/$IMAGE_TAR"
        else
            say "install-offline: neither docker nor ctr is installed"; exit 1
        fi
        repo="$IMAGE_REPO"; [ -z "$registry" ] || repo="$registry/$IMAGE_REPO"
        say "install-offline: image $IMAGE_REF loaded"
        say "  helm install <release> chart/$CHART_TGZ --set image.repository=$repo --set secrets.existingSecret=<your OIDC secret>" ;;
    *)
        sed -n '2,10p' "$self"; exit 2 ;;
esac
